"""Render docs/APP_INDICATORS.md from app_risk specs (single source of truth).

    .venv/Scripts/python.exe scripts/render_indicator_docs.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from app_risk import config as C  # noqa: E402
from app_risk.data import SQL  # noqa: E402
from app_risk.indicators import CLAIM_SPEC, DISCLAIMER, PROVIDER_SPEC  # noqa: E402


def main() -> None:
    L = [f"# Application-native risk indicators (`{C.INDICATOR_SET_KEY}` v{C.INDICATOR_SET_VERSION})", "",
         "_Generated by `scripts/render_indicator_docs.py` from `app_risk/`. Edit the code, not this file._", "",
         f"> {DISCLAIMER}", "",
         "## Data used (read-only, column-whitelisted)", "",
         "| Query | SQL |", "|---|---|"]
    L += [f"| {k} | `{v}` |" for k, v in SQL.items()]
    L += ["", f"Never loaded or used: {', '.join(f'`{c}`' for c in sorted(C.FORBIDDEN_COLUMNS))} "
          "(post-review decisions would leak the outcome; patient personal or sensitive fields are not needed). "
          "The loader rejects data containing them, and the MySQL session is read-only.", "",
          "## History cutoff (no look-ahead)", "",
          "- **Claim level:** history = claims with a smaller `CLAIM_ID` (inserted earlier; `CLAIM_ID` is AUTO_INCREMENT). Date windows use "
          "`CLAIM_DATE` within that history. Later claims, including back-dated ones, never change an earlier claim's result, "
          "so re-assessing a claim later gives the same result.",
          "- **Provider level:** claims with `CLAIM_DATE` ≤ the as-of date, compared with peers at the same cutoff.",
          "- **Dates** are calendar dates from MySQL (`DATE`), not converted through any timezone (tested under IST).", "",
          "## Claim-level indicators", "",
          "| Code | Name | Inputs | Calculation | Why | Triggered when |", "|---|---|---|---|---|---|"]
    L += [f"| `{k}` | {v[0]} | {v[1]} | {v[2]} | {v[3]} | {v[4]} |" for k, v in CLAIM_SPEC.items()]
    L += ["", "Statuses: `ok`; `insufficient_history` (not enough earlier data, so `triggered` is null); "
          "`not_applicable` (e.g. no previous claim). Insufficient history is never filled with a default.", "",
          "### Review priority (ordering aid, not a score or a decision)", "",
          "- **High:** any existing SQL rule hit on the claim, or ≥ 2 triggered indicators",
          "- **Elevated:** exactly 1 triggered indicator",
          "- **Routine:** otherwise", "",
          "Reasons are always listed. Priority never changes `CLAIM.STATUS` and never approves or rejects a claim.", "",
          "## Provider-level indicators", "",
          f"Ratio indicators need ≥ {C.MIN_PROVIDER_CLAIMS} claims. Peer comparison needs ≥ {C.MIN_PEERS} other providers with ≥ "
          f"{C.MIN_PROVIDER_CLAIMS} claims; \"unusually high\" means above the peers' {C.PEER_HIGH_PERCENTILE}th percentile, and "
          f"\"unusually low\" below their {C.PEER_LOW_PERCENTILE}th.", "",
          "| Code | Name | Calculation | Peer comparison |", "|---|---|---|---|"]
    L += [f"| `{k}` | {v[0]} | {v[1]} | {({'high': 'flag if unusually high', 'low': 'flag if unusually low'}).get(v[2], 'informational')} |"
          for k, v in PROVIDER_SPEC.items()]
    L += ["", "Provider-level and claim-level results are reported separately and never combined into one number.", "",
          "## Configured thresholds", "", "| Setting | Value |", "|---|---|"]
    L += [f"| `{k}` | {getattr(C, k)} |" for k in dir(C) if k.isupper() and k not in ("FORBIDDEN_COLUMNS", "INDICATOR_SET_KEY", "INDICATOR_SET_VERSION")]
    L += ["", "Thresholds are design choices, not learned values: the application has no labelled outcomes yet. "
          "Changing any of them requires a new indicator-set version.", ""]
    out = ROOT / "docs" / "APP_INDICATORS.md"
    out.write_text("\n".join(L), encoding="utf-8")
    print(f"Wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
